  return(x^2/4);
}

real a, b, c;
pair A, B, C, F;

a = -2; b = 1.5; c = 3;
A = (a,func(a));
B = (b,func(b));
C = (c,func(c));
F = (0,1);

draw(graph(func,-4,5),red);
draw(Circle(A,abs(A - F)));
draw(Circle(B,abs(B - F)));
draw(Circle(C,abs(C - F)));
draw((-4,-1)--(6,-1));
draw(A--F,dashed);
draw(B--F,dashed);
draw(C--F,dashed);
draw(A--(a,-1),dashed);
draw(B--(b,-1),dashed);
draw(C--(c,-1),dashed);
draw((-3,-2)--(-3,5.5));

